<script setup lang="ts">import{ref,onMounted,computed}from'vue';import AppShell from'../components/AppShell.vue';import{api}from'../services/api';const month=ref(new Date().toISOString().slice(0,7)),items=ref<any[]>([]),history=ref<any[]>([]);async function load(){items.value=(await api(`/api/stats/personal?month=${month.value}`)).items;history.value=(await api('/api/leave-requests')).items}onMounted(()=>load().catch(()=>{}));const n=(t:string)=>items.value.find(x=>x.request_type===t)?.count||0;const lateMinutes=computed(()=>items.value.find(x=>x.request_type==='LATE')?.minutes||0)</script><template><AppShell><main class="page"><div class="head"><div><div class="title">Thống kê cá nhân</div><div class="muted">Theo dõi tình hình làm việc và các yêu cầu của bạn</div></div><v-text-field v-model="month" type="month" density="compact" hide-details @change="load"/></div><div class="stats"><div class="card"><v-icon>mdi-briefcase</v-icon><b>—</b><span>Ngày làm việc</span></div><div class="card amber"><v-icon>mdi-clock</v-icon><b>{{n('LATE')}}</b><span>Lần đi muộn</span></div><div class="card red"><v-icon>mdi-airplane</v-icon><b>{{n('ANNUAL_LEAVE')+n('FULL_DAY_LEAVE')}}</b><span>Ngày nghỉ phép</span></div><div class="card purple"><v-icon>mdi-home</v-icon><b>—</b><span>Làm việc từ xa</span></div></div><div class="charts"><div class="card"><h3>Thời gian đi muộn</h3><div class="big">{{lateMinutes}} <small>phút</small></div><div class="bar"><i :style="{width:Math.min(100,lateMinutes/1.2)+'%'}"></i></div></div><div class="card"><h3>Tỷ lệ loại yêu cầu</h3><div v-for="x in items" class="row"><span>{{x.request_type}}</span><b>{{x.count}}</b></div><div v-if="!items.length" class="muted">Chưa có dữ liệu trong tháng.</div></div></div><div class="card history"><h3>Lịch sử yêu cầu của tôi</h3><div class="request" v-for="x in history.slice(0,8)"><div><b>{{x.request_type}}</b><small>{{x.start_date}} · {{x.reason}}</small></div><span :class="['pill',x.status]">{{x.status}}</span></div></div></main></AppShell></template><style scoped>.head{display:flex;justify-content:space-between;gap:20px;align-items:center}.head .v-text-field{max-width:180px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:20px 0}.stats .card{text-align:center}.stats b{display:block;font-size:32px;color:#16a34a}.stats .v-icon{color:#16a34a}.amber b,.amber .v-icon{color:#f59e0b}.red b,.red .v-icon{color:#ef4444}.purple b,.purple .v-icon{color:#7c3aed}.charts{display:grid;grid-template-columns:1fr 1fr;gap:14px}.card h3{color:#8b0d24}.big{font-size:48px;font-weight:800;color:#8b0d24}.big small{font-size:15px}.bar{height:16px;background:#fdecef;border-radius:10px;overflow:hidden}.bar i{display:block;height:100%;background:#8b0d24}.row,.request{display:flex;justify-content:space-between;padding:11px 0;border-bottom:1px solid #eee}.history{margin-top:14px}.request small{display:block;color:#697386}.pill{padding:5px 9px;border-radius:12px;background:#eee;font-size:11px}.APPROVED{background:#e8f8ed;color:#16803b}.PENDING{background:#fff4dd;color:#b76b00}.REJECTED{background:#ffe8eb;color:#b91c2f}@media(max-width:700px){.stats{grid-template-columns:repeat(2,1fr)}.charts{grid-template-columns:1fr}.head{align-items:flex-start}.head .v-text-field{max-width:145px}}</style>
